const timeZone = 'America/New_York';

// Use the trigger timestamp instead of the server clock
const now = new Date($input.first().json.timestamp);

const currentDate = new Date(
  now.getFullYear(),
  now.getMonth(),
  1,
  12
);

const previousDate = new Date(
  now.getFullYear(),
  now.getMonth() - 1,
  1,
  12
);

const currentMonth = new Intl.DateTimeFormat('en-US', {
  timeZone,
  month: 'long',
  year: 'numeric',
}).format(currentDate);

const previousMonth = new Intl.DateTimeFormat('en-US', {
  timeZone,
  month: 'long',
  year: 'numeric',
}).format(previousDate);

return [
  {
    json: {
      currentMonth,
      previousMonth,
    },
  },
];

/**
 * n8n Code node
 *
 * Input: Previous month's Sales Goals record from Airtable
 * Output: Recommended goals for the current month
 */

const input = $input.first().json;

// Airtable may return fields directly or inside a `fields` object.
const data = input.fields ?? input;

function toNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function roundTo(value, increment) {
  if (!Number.isFinite(value) || increment <= 0) return 0;
  return Math.round(value / increment) * increment;
}

function clamp(value, minimum, maximum) {
  return Math.min(Math.max(value, minimum), maximum);
}

// -----------------------------------------------------
// Month names
// -----------------------------------------------------

const now = new Date();

const currentMonth = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/New_York",
  month: "long",
  year: "numeric",
}).format(now);

const previousMonthDate = new Date(
  now.getFullYear(),
  now.getMonth() - 1,
  1
);

const previousMonth = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/New_York",
  month: "long",
  year: "numeric",
}).format(previousMonthDate);

// -----------------------------------------------------
// Previous goals
// -----------------------------------------------------

const previousRevenueGoal = toNumber(data["Revenue Goal"]);
const previousCallsGoal = toNumber(data["Calls Goal"]);
const previousDealsGoal = toNumber(data["Deals Goal"]);
const previousCashGoal = toNumber(data["Cash Collected Goal"]);

// -----------------------------------------------------
// Previous actual performance
// -----------------------------------------------------

const revenueClosed = toNumber(data["Revenue Closed"]);
const cashCollected = toNumber(data["Cash Collected"]);

const totalCallsBooked = toNumber(data["Total Calls Booked"]);
const totalCallsHeld = toNumber(data["Total Calls Held"]);
const totalOffersMade = toNumber(data["Total Offers Made"]);
const totalDealsClosed = toNumber(data["Total Deals Closed"]);

const bookingToShowRate =
  totalCallsBooked > 0
    ? totalCallsHeld / totalCallsBooked
    : toNumber(data["Booking → Show Rate"]);

const bookingToCloseRate =
  totalCallsBooked > 0
    ? totalDealsClosed / totalCallsBooked
    : toNumber(data["Booking → Close Rate"]);

const showToOfferRate =
  totalCallsHeld > 0
    ? totalOffersMade / totalCallsHeld
    : 0;

const offerToCloseRate =
  totalOffersMade > 0
    ? totalDealsClosed / totalOffersMade
    : 0;

const averageDealSize =
  totalDealsClosed > 0
    ? revenueClosed / totalDealsClosed
    : 0;

const callsPerClose =
  totalDealsClosed > 0
    ? totalCallsBooked / totalDealsClosed
    : null;

const rawAverageDaysToClose = toNumber(data["Avg Days to Close"]);

const averageDaysToClose =
  rawAverageDaysToClose >= 0
    ? rawAverageDaysToClose
    : null;

// -----------------------------------------------------
// Goal attainment
// -----------------------------------------------------

const revenueAttainment =
  previousRevenueGoal > 0
    ? revenueClosed / previousRevenueGoal
    : 0;

const callsAttainment =
  previousCallsGoal > 0
    ? totalCallsBooked / previousCallsGoal
    : 0;

const dealsAttainment =
  previousDealsGoal > 0
    ? totalDealsClosed / previousDealsGoal
    : 0;

/**
 * Revenue and closed deals matter more than booked-call volume.
 */
const weightedAttainment =
  revenueAttainment * 0.45 +
  dealsAttainment * 0.35 +
  callsAttainment * 0.20;

// -----------------------------------------------------
// Sample-size confidence
// -----------------------------------------------------

let confidence = "low";

if (totalCallsBooked >= 25 && totalDealsClosed >= 3) {
  confidence = "high";
} else if (totalCallsBooked >= 10 || totalDealsClosed >= 2) {
  confidence = "medium";
}

// -----------------------------------------------------
// Base growth recommendation
// -----------------------------------------------------

let growthRate;

if (weightedAttainment >= 1.25) {
  growthRate = 0.20;
} else if (weightedAttainment >= 1.05) {
  growthRate = 0.12;
} else if (weightedAttainment >= 0.90) {
  growthRate = 0.05;
} else if (weightedAttainment >= 0.70) {
  growthRate = 0;
} else if (weightedAttainment >= 0.50) {
  growthRate = -0.05;
} else {
  growthRate = -0.10;
}

/**
 * Avoid aggressive increases based on a very small sample.
 */
if (confidence === "low") {
  growthRate = clamp(growthRate, -0.05, 0.05);
} else if (confidence === "medium") {
  growthRate = clamp(growthRate, -0.10, 0.12);
} else {
  growthRate = clamp(growthRate, -0.10, 0.20);
}

// -----------------------------------------------------
// New calls goal
// -----------------------------------------------------

let recommendedCallsGoal = Math.round(
  previousCallsGoal * (1 + growthRate)
);

recommendedCallsGoal = Math.max(
  1,
  recommendedCallsGoal
);

// Keep calls goals in clean increments of five.
recommendedCallsGoal = Math.max(
  5,
  roundTo(recommendedCallsGoal, 5)
);

// -----------------------------------------------------
// New deals goal
// -----------------------------------------------------

let recommendedDealsGoal;

/**
 * When enough conversion data exists, calculate deals from the
 * recommended call volume. Otherwise, grow the previous goal.
 */
if (totalCallsBooked >= 10 && bookingToCloseRate > 0) {
  recommendedDealsGoal = Math.round(
    recommendedCallsGoal * bookingToCloseRate
  );
} else {
  recommendedDealsGoal = Math.round(
    previousDealsGoal * (1 + growthRate)
  );
}

recommendedDealsGoal = Math.max(
  1,
  recommendedDealsGoal
);

// Prevent deals goal from changing too dramatically.
const minimumDealsGoal = Math.max(
  1,
  Math.floor(previousDealsGoal * 0.8)
);

const maximumDealsGoal = Math.max(
  previousDealsGoal + 1,
  Math.ceil(previousDealsGoal * 1.25)
);

recommendedDealsGoal = clamp(
  recommendedDealsGoal,
  minimumDealsGoal,
  maximumDealsGoal
);

// -----------------------------------------------------
// New revenue goal
// -----------------------------------------------------

let recommendedRevenueGoal;

if (averageDealSize > 0) {
  recommendedRevenueGoal =
    recommendedDealsGoal * averageDealSize;
} else {
  recommendedRevenueGoal =
    previousRevenueGoal * (1 + growthRate);
}

/**
 * Keep the calculated revenue goal within reasonable bounds compared
 * with the previous goal.
 */
const minimumRevenueGoal =
  previousRevenueGoal > 0
    ? previousRevenueGoal * 0.90
    : 0;

const maximumRevenueGoal =
  previousRevenueGoal > 0
    ? previousRevenueGoal * 1.25
    : recommendedRevenueGoal;

recommendedRevenueGoal = clamp(
  recommendedRevenueGoal,
  minimumRevenueGoal,
  maximumRevenueGoal
);

// Use clean $1,000 increments.
recommendedRevenueGoal = roundTo(
  recommendedRevenueGoal,
  1000
);

// -----------------------------------------------------
// New cash goal
// -----------------------------------------------------

let recommendedCashGoal;

if (previousCashGoal > 0) {
  recommendedCashGoal = previousCashGoal * (1 + growthRate);
} else {
  // First month: default to actual cash collected,
  // otherwise fall back to the revenue goal.
  recommendedCashGoal =
    cashCollected > 0
      ? cashCollected
      : recommendedRevenueGoal;
}

const minimumCashGoal =
  previousCashGoal > 0
    ? previousCashGoal * 0.90
    : 0;

const maximumCashGoal =
  previousCashGoal > 0
    ? previousCashGoal * 1.25
    : recommendedCashGoal;

recommendedCashGoal = clamp(
  recommendedCashGoal,
  minimumCashGoal,
  maximumCashGoal
);

recommendedCashGoal = roundTo(
  recommendedCashGoal,
  1000
);

// -----------------------------------------------------
// Explanation
// -----------------------------------------------------

let reason;

if (weightedAttainment >= 1.25) {
  reason =
    "The previous month materially exceeded the weighted goals, so the targets were increased while remaining capped for sustainability.";
} else if (weightedAttainment >= 1.05) {
  reason =
    "The previous month exceeded its weighted goals, supporting a moderate increase in targets.";
} else if (weightedAttainment >= 0.90) {
  reason =
    "Performance was close to goal, so the targets were increased only slightly.";
} else if (weightedAttainment >= 0.70) {
  reason =
    "Performance was below goal but reasonably close, so the targets were kept approximately stable.";
} else {
  reason =
    "Performance was materially below goal, so the targets were reduced modestly rather than reset aggressively.";
}

// -----------------------------------------------------
// Return structured data for the AI reviewer and Airtable
// -----------------------------------------------------

return [
  {
    json: {
      previousMonth,
      currentMonth,

previousGoals: {
  revenueGoal: previousRevenueGoal,
  cashGoal: previousCashGoal,
  callsGoal: previousCallsGoal,
  dealsGoal: previousDealsGoal,
},

      actualPerformance: {
        revenueClosed,
        cashCollected,
        totalCallsBooked,
        totalCallsHeld,
        totalOffersMade,
        totalDealsClosed,
        averageDealSize,
        callsPerClose,
        averageDaysToClose,
      },

      conversionMetrics: {
        bookingToShowRate,
        showToOfferRate,
        offerToCloseRate,
        bookingToCloseRate,
      },

      attainment: {
        revenueAttainment,
        callsAttainment,
        dealsAttainment,
        weightedAttainment,
      },

javascriptRecommendation: {
  month: currentMonth,
  revenueGoal: recommendedRevenueGoal,
  callsGoal: recommendedCallsGoal,
  dealsGoal: recommendedDealsGoal,
  cashGoal: recommendedCashGoal,

  projectedGrowthRate:
    previousRevenueGoal > 0
      ? Number(
          (
            (recommendedRevenueGoal - previousRevenueGoal) /
            previousRevenueGoal
          ).toFixed(4)
        )
      : 0,

  confidence,
  reason,
},
    },
  },
];

const response = $input.first().json;

const aiText =
  response.output?.[0]?.content?.[0]?.text;

if (!aiText) {
  throw new Error("Could not find AI JSON text in output[0].content[0].text");
}

const ai = JSON.parse(aiText);

const baseline =
  $("new targets suggestions").first().json.javascriptRecommendation;

const toNumber = (value, fallback) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const clamp = (value, min, max) =>
  Math.min(Math.max(value, min), max);

const revenueBaseline = toNumber(baseline.revenueGoal, 0);
const cashBaseline = toNumber(baseline.cashGoal, 0);
const callsBaseline = toNumber(baseline.callsGoal, 1);
const dealsBaseline = toNumber(baseline.dealsGoal, 1);

let revenueGoal = toNumber(ai.revenueGoal, revenueBaseline);
let cashGoal = toNumber(ai.cashGoal, cashBaseline);
let callsGoal = toNumber(ai.callsGoal, callsBaseline);
let dealsGoal = toNumber(ai.dealsGoal, dealsBaseline);

// Limit AI adjustments to ±10%
revenueGoal = clamp(
  revenueGoal,
  revenueBaseline * 0.9,
  revenueBaseline * 1.1
);

cashGoal = clamp(
  cashGoal,
  cashBaseline * 0.9,
  cashBaseline * 1.1
);

callsGoal = clamp(
  callsGoal,
  callsBaseline * 0.9,
  callsBaseline * 1.1
);

dealsGoal = clamp(
  dealsGoal,
  dealsBaseline * 0.9,
  dealsBaseline * 1.1
);

// Clean final values
revenueGoal = Math.round(revenueGoal / 1000) * 1000;
cashGoal = Math.round(cashGoal / 1000) * 1000;
callsGoal = Math.max(1, Math.round(callsGoal));
dealsGoal = Math.max(1, Math.round(dealsGoal));

// Preserve the growth rate calculated by the first JavaScript node
const projectedGrowthRate =
  baseline.growthRate ??
  baseline.projectedGrowthRate ??
  baseline.estimatedGrowthRate ??
  ai.growthRate ??
  ai.projectedGrowthRate ??
  ai.estimatedGrowthRate ??
  0;

return [
  {
    json: {
      month: baseline.month,

      revenueGoal,
      cashGoal,
      callsGoal,
      dealsGoal,

      projectedGrowthRate,

      confidence: ai.confidence ?? baseline.confidence,

      approvedWithoutChanges:
  revenueGoal === revenueBaseline &&
  cashGoal === cashBaseline &&
  callsGoal === callsBaseline &&
  dealsGoal === dealsBaseline,

      reason: ai.reason ?? baseline.reason,
    },
  },
];
